package com.aurum.scalp;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class DebugRegressionTest {
 static final long T=java.time.Instant.parse("2026-11-13T12:00:00Z").toEpochMilli();
 private Market.Quote q(long t,double p){return new Market.Quote(t,p-.1,p+.1);}
 private Market.Candle c(double close){return new Market.Candle(T,4000,4030,3990,close,T+60000);}
 @Test public void newerProviderSnapshotReplacesOldTickClose(){FormingBook b=new FormingBook();b.tick(q(T+1000,4002),true,T+1000);b.seed(Market.Frame.M1,c(4020),T+5000);assertEquals(4020,b.visible(Market.Frame.M1,0,T+5000,q(T+5000,4020),true).get(0).candle.close,0);}
 @Test public void olderSnapshotCannotOverwriteNewerTickClose(){FormingBook b=new FormingBook();b.tick(q(T+5000,4002),true,T+5000);b.seed(Market.Frame.M1,c(4020),T+1000);assertEquals(4002,b.visible(Market.Frame.M1,0,T+5000,q(T+5000,4002),true).get(0).candle.close,0);}
 @Test public void delayedTickCannotOverwriteNewerSnapshotClose(){FormingBook b=new FormingBook();b.seed(Market.Frame.M1,c(4020),T+5000);b.tick(q(T+2000,4002),true,T+5000);assertEquals(4020,b.visible(Market.Frame.M1,0,T+5000,q(T+5000,4020),true).get(0).candle.close,0);}
 @Test public void reopenRefreshesHistoryWithoutBypassing429(){PollPolicy p=new PollPolicy();p.claim("quote",100,false);p.complete("quote",100,60000,false);p.claim("H1",100,false);p.complete("H1",100,600000,false);assertFalse(p.claim("H1",200,false));p.marketOpened();assertTrue(p.claim("quote",200,false));assertTrue(p.claim("H1",200,false));p.complete("H1",200,60000,true);p.marketOpened();assertFalse(p.claim("M1",300,true));assertEquals(59900,p.remaining(300));}
 @Test public void futureLastCloseIsNeverFresh(){ZoneEngine.Analysis a=new ZoneEngine.Analysis(Market.Frame.M1,Collections.singletonList(c(4000)),Collections.emptyList(),Collections.emptyList(),2,0,"range");assertFalse(a.historyFresh(T+30000));assertTrue(a.historyFresh(T+60000));}
 @Test public void candleReferenceStateAgreesWithDisplayedPrice(){ZoneEngine.Analysis a=new ZoneEngine.Analysis(Market.Frame.M1,Collections.singletonList(c(4000)),Collections.emptyList(),Collections.emptyList(),2,0,"range");assertEquals("● CANDLE REFERENCE",Market.priceState(q(T-1000,3900),false,T+70000,Collections.singletonList(a)));assertEquals("● CANDLE REFERENCE",Market.priceState(null,false,T+70000,Collections.singletonList(a)));}
 @Test public void closedSessionAndUnknownClockAreDifferentLabels(){ZoneEngine.Analysis a=new ZoneEngine.Analysis(Market.Frame.M1,Collections.singletonList(c(4000)),Collections.emptyList(),Collections.emptyList(),2,0,"range");assertTrue(Market.historyState(a,T+86400000,new Market.Quote(T,4000,4001,true,false)).contains("MARKET CLOSED"));assertEquals("TIME UNVERIFIED",Market.historyState(a,0,q(T,4000)));assertTrue(Market.historyState(a,T+86400000,q(T,4000)).contains("OUTDATED"));}
 private String body(Object flag)throws Exception{JSONArray bars=new JSONArray();bars.put(new JSONObject().put("openTime",java.time.Instant.ofEpochMilli(T).toString()).put("open",4000).put("high",4002).put("low",3998).put("close",4001).put("isOpen",flag));return new JSONObject().put("symbol","XAUUSD").put("interval","1m").put("bars",bars).toString();}
 @Test public void closureFlagMustBeARealBoolean()throws Exception{assertEquals(0,BiquoteCodec.candles(body("false"),Market.Frame.M1,T+60000,0).size());assertEquals(1,BiquoteCodec.candles(body(false),Market.Frame.M1,T+60000,0).size());}
 @Test public void formingFlagMustBeARealBoolean()throws Exception{assertNull(BiquoteCodec.forming(body("true"),Market.Frame.M1,T+1000));assertNotNull(BiquoteCodec.forming(body(true),Market.Frame.M1,T+1000));assertNull(BiquoteCodec.forming(body(true),Market.Frame.M1,T+60000));}
 @Test public void unknownStreamSessionStateCannotOpenTheMarket(){final int[] calls={0};BiquoteStreamTest.Recorder r=new BiquoteStreamTest.Recorder(){@Override public void state(boolean c){calls[0]++;}};BiquoteStreamTest.Socket s=new BiquoteStreamTest.Socket(r);s.onMessage("{}\u001e");s.onMessage("{\"type\":1,\"target\":\"ReceiveSubscriptionState\",\"arguments\":[[{\"symbol\":\"XAUUSD\",\"state\":\"unknown\"}]]}\u001e");assertEquals(0,calls[0]);}
}
